import json,urllib.request,subprocess,shutil
out={'ollamaInstalled':bool(shutil.which('ollama')),'readOnly':True}
for p in ('http://127.0.0.1:11434/api/tags','http://127.0.0.1:11434/api/ps'):
 try:
  with urllib.request.urlopen(p,timeout=3) as x:d=json.load(x)
  if p.endswith('/tags'):out['installedModels']=[str(x.get('name',''))[:80] for x in d.get('models',[])][:12]
  else:out['loadedModels']=[str(x.get('name',''))[:80] for x in d.get('models',[])][:12]
 except Exception as e:out['error_'+p.rsplit('/',1)[-1]]=type(e).__name__
print(json.dumps(out,ensure_ascii=True)[:2600])
